const ROOT_DISPATCH_BY_LOCAL_NAME = new Map<
  string,
  ContentParser<OurTypes.Class>
>([
  ["something", parseSomethingFromSequence],
  ["collection", parseCollectionFromSequence]
]);

/**
 * Parse an XML string as a model instance.
 *
 * @param xml - XML string to parse
 * @returns parsed model instance or an error
 */
export function fromXmlString(
  xml: string
): OurCommon.Either<OurTypes.Class, DeserializationError> {
  if (xml.length === 0) {
    return newDeserializationError<OurTypes.Class>(
      "Expected an XML document, but got an empty string"
    );
  }

  const tokensOrError = tokenizeXml(xml);
  if (tokensOrError.error !== null) {
    return new OurCommon.Either<OurTypes.Class, DeserializationError>(
      null,
      tokensOrError.error
    );
  }

  const cursor = new XmlCursor(tokensOrError.mustValue());

  const rootOpenTagOrError = readRequiredRootOpenTag(cursor);
  if (rootOpenTagOrError.error !== null) {
    return new OurCommon.Either<OurTypes.Class, DeserializationError>(
      null,
      rootOpenTagOrError.error
    );
  }

  const rootOpenTag = rootOpenTagOrError.mustValue();
  const rootLocalName = localNameOfTag(rootOpenTag.tag);

  // NOTE (mristin):
  // The errors within the root element are reported at it, as in the other SDKs.
  const dispatch = ROOT_DISPATCH_BY_LOCAL_NAME.get(rootLocalName);
  if (dispatch === undefined) {
    const error = new DeserializationError(
      `Unexpected root XML element: ${rootLocalName}`
    );
    error.path.prepend(new ElementSegment(rootLocalName));
    return new OurCommon.Either<OurTypes.Class, DeserializationError>(
      null,
      error
    );
  }

  const instanceOrError = dispatch(cursor);
  if (instanceOrError.error !== null) {
    instanceOrError.error.path.prepend(new ElementSegment(rootLocalName));
    return instanceOrError;
  }

  const closeError = consumeCloseTag(cursor, rootLocalName);
  if (closeError !== null) {
    closeError.path.prepend(new ElementSegment(rootLocalName));
    return new OurCommon.Either<OurTypes.Class, DeserializationError>(
      null,
      closeError
    );
  }

  cursor.skipIgnorable();
  if (cursor.current() !== null) {
    return newDeserializationError<OurTypes.Class>(
      "Expected no tokens after the root XML element, but got token kind: " +
        currentTokenKind(cursor)
    );
  }

  return instanceOrError;
}

/**
 * Write the instances of `values`, each as its own, self-describing XML element.
 *
 * @remarks
 *
 * Every item goes through {@link writeClass} whatever its declared type is, so
 * this one writer serves every list of instances in the meta-model.
 */
function writeListOfInstances(
  parts: Array<string>,
  values: Array<OurTypes.Class>
): void {
  writeList(parts, values, writeClass);
}

/**
 * Write `that` as its own, self-describing XML element.
 *
 * @remarks
 *
 * Which element that is, is decided by the run-time type of `that`, so this one
 * writer serves every abstract class, every named union, and the item of a list
 * or of a tuple of any class at all. The reading, which has to decide what to
 * construct before it has read anything, needs a dispatcher per interface instead.
 */
function writeClass(parts: Array<string>, that: OurTypes.Class): void {
  SERIALIZER.visitWithContext(that, parts);
}

/**
 * Write the literal `value` of the enumeration `enumerationName` as the content
 * of an XML element.
 *
 * @remarks
 *
 * We deliberately go through the `toString` of the stringification module, which
 * gives out `null` for a literal it does not know, and not through its `mustToString`,
 * which throws an error of its own. An instance carrying a literal outside its
 * enumeration is exactly the kind of failure this module reports with a path.
 */
function writeEnumerationContent<T>(
  parts: Array<string>,
  value: T,
  enumerationName: string,
  toString: (value: T) => string | null
): void {
  const text = toString(value);
  if (text === null) {
    throw new SerializationError(
      `Invalid literal of ${enumerationName}: ${value}`
    );
  }

  parts.push(escapeXmlText(text));
}

function write_bool(
  parts: Array<string>,
  value: boolean
): void {
  parts.push(value ? "true" : "false");
}

function write_int(
  parts: Array<string>,
  value: number
): void {
  // NOTE (mristin):
  // Beyond the safe integers a ``number`` no longer holds every integer, so
  // the value we were handed has already lost its identity -- writing it out
  // would record a different xs:long without a word.
  if (!Number.isInteger(value)) {
    throw new SerializationError(OurCommon.notWholeIntegerMessage(value));
  }
  if (!Number.isSafeInteger(value)) {
    throw new SerializationError(OurCommon.unsafeIntegerMessage(value));
  }

  parts.push(`${value}`);
}

function write_float(
  parts: Array<string>,
  value: number
): void {
  if (Number.isNaN(value)) {
    parts.push("NaN");
  } else if (value === Infinity) {
    parts.push("INF");
  } else if (value === -Infinity) {
    parts.push("-INF");
  } else if (Object.is(value, -0)) {
    // NOTE (mristin):
    // ``${-0}`` is "0", so the sign would be dropped, and a negative zero
    // would come back as a positive one. ``-0`` is a valid xs:double, and
    // the other SDKs keep the sign, so we keep it too. Mind that
    // ``value === -0`` is true for a positive zero as well, which is why
    // this asks ``Object.is``.
    parts.push("-0");
  } else {
    parts.push(`${value}`);
  }
}

function write_str(
  parts: Array<string>,
  value: string
): void {
  parts.push(escapeXmlText(value));
}

function write_bytes(
  parts: Array<string>,
  value: Uint8Array
): void {
  parts.push(escapeXmlText(OurCommon.base64Encode(value)));
}

/**
 * Write the XML element of an instance, dispatching on its run-time type.
 *
 * Each method writes the whole element -- the tags included -- since the element
 * is picked by the run-time type, which this dispatch has just established. The
 * properties are written by the corresponding module-level `write{Cls}AsSequence`,
 * which is the content writer of that very element.
 */
class Serializer extends OurTypes.AbstractVisitorWithContext<Array<string>> {
  visitSomethingWithContext(
    that: OurTypes.Something,
    parts: Array<string>
  ): void {
    writeElement(
      parts,
      "something",
      that,
      writeSomethingAsSequence
    );
  }

  visitCollectionWithContext(
    that: OurTypes.Collection,
    parts: Array<string>
  ): void {
    writeElement(
      parts,
      "collection",
      that,
      writeCollectionAsSequence
    );
  }
}

const SERIALIZER = new Serializer();

/**
 * Serialize a model instance as an XML string.
 *
 * @param that - model instance to serialize
 * @returns serialized XML string
 * @throws {@link SerializationError} if `that` can not be serialized, *e.g.*, if
 * a property expected to be an integer holds a fractional number
 */
export function toXmlString(that: OurTypes.Class): string {
  const parts = new Array<string>();
  writeClass(parts, that);
  return parts.join("");
}

